const incoming = $input.first().json;
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const issues = [];
const text = typeof body.text === 'string' ? body.text.trim() : '';
const context = body.context && typeof body.context === 'object' ? body.context : {};
const topVacancyId = body.vacancy_id;
const nestedVacancyId = context.vacancy_id;
const rawVacancyId = nestedVacancyId ?? topVacancyId;
const vacancyId = Number(rawVacancyId);
const rawCandidateId = context.candidate_id ?? body.candidate_id ?? 0;
const candidateId = rawCandidateId === null || rawCandidateId === '' ? 0 : Number(rawCandidateId);

if (!text) issues.push({ path: 'text', message: 'Нужен непустой текст запроса.' });
if (!Number.isInteger(vacancyId) || vacancyId <= 0) {
  issues.push({ path: 'context.vacancy_id', message: 'Нужен положительный целый идентификатор вакансии.' });
}
if (topVacancyId !== undefined && nestedVacancyId !== undefined && Number(topVacancyId) !== Number(nestedVacancyId)) {
  issues.push({ path: 'vacancy_id', message: 'Идентификатор вакансии в корне и context не совпадает.' });
}
if (!Number.isInteger(candidateId) || candidateId < 0) {
  issues.push({ path: 'context.candidate_id', message: 'Идентификатор кандидата должен быть положительным целым числом либо отсутствовать.' });
}

return [{
  json: {
    valid: issues.length === 0,
    issues,
    request_id: typeof body.request_id === 'string' && body.request_id ? body.request_id : 'lab-' + $execution.id,
    session_id: typeof body.session_id === 'string' && body.session_id ? body.session_id : 'lab-' + $execution.id,
    text,
    vacancy_id: vacancyId,
    candidate_id: candidateId,
  },
}];
